import bisect

class Solution:
    def maximumWhiteTiles(self, tiles: list[list[int]], carpetLen: int) -> int:
        tiles.sort(key=lambda x: x[0])
        n = len(tiles)
        starts = [t[0] for t in tiles]
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + (tiles[i][1] - tiles[i][0] + 1)

        ans = 0
        for i in range(n):
            carpet_end = tiles[i][0] + carpetLen - 1
            idx = bisect.bisect_right(starts, carpet_end) - 1
            total = prefix[idx] - prefix[i]
            if tiles[idx][1] <= carpet_end:
                total += (tiles[idx][1] - tiles[idx][0] + 1)
            else:
                total += (carpet_end - tiles[idx][0] + 1)
            ans = max(ans, total)
        return ans

class Solution {
public:
    int maximumWhiteTiles(std::vector<std::vector<int>>& tiles, int carpetLen) {
        std::sort(tiles.begin(), tiles.end(), [](const auto& a, const auto& b) { return a[0] < b[0]; });
        int n = tiles.size();
        std::vector<int> starts(n);
        std::vector<long long> prefix(n + 1, 0);
        for (int i = 0; i < n; ++i) {
            starts[i] = tiles[i][0];
            prefix[i + 1] = prefix[i] + (tiles[i][1] - tiles[i][0] + 1);
        }
        long long ans = 0;
        for (int i = 0; i < n; ++i) {
            int carpet_end = tiles[i][0] + carpetLen - 1;
            int idx = std::upper_bound(starts.begin(), starts.end(), carpet_end) - starts.begin() - 1;
            long long total = prefix[idx] - prefix[i];
            if (tiles[idx][1] <= carpet_end) {
                total += (tiles[idx][1] - tiles[idx][0] + 1);
            } else {
                total += (carpet_end - tiles[idx][0] + 1);
            }
            ans = std::max(ans, total);
        }
        return ans;
    }
};

class Solution {
    public int maximumWhiteTiles(int[][] tiles, int carpetLen) {
        java.util.Arrays.sort(tiles, (a, b) -> Integer.compare(a[0], b[0]));
        int n = tiles.length;
        int[] starts = new int[n];
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            starts[i] = tiles[i][0];
            prefix[i + 1] = prefix[i] + (tiles[i][1] - tiles[i][0] + 1);
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
            int carpetEnd = tiles[i][0] + carpetLen - 1;
            int lo = 0, hi = n - 1, idx = i;
            while (lo <= hi) {
                int mid = (lo + hi) >>> 1;
                if (starts[mid] <= carpetEnd) {
                    idx = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            long total = prefix[idx] - prefix[i];
            if (tiles[idx][1] <= carpetEnd) {
                total += (tiles[idx][1] - tiles[idx][0] + 1);
            } else {
                total += (carpetEnd - tiles[idx][0] + 1);
            }
            ans = Math.max(ans, total);
        }
        return (int) ans;
    }
}

